nned"}, {"agency_code": "beth_din_paris", "code": "paris_commerces", "name_he": "בית הדין פריז — בתי עסק", "url": "https://www.consistoire.org/commerces/", "content_kind": "establishments", "notes": "מכשיר Beth Din de Paris; מפרסם Consistoire de Paris. העמוד מזהיר שרשימת בתי העסק משתנה. הרשאה, מזהים ושלמות טרם הושלמו.", "format": "html", "completeness": "unknown", "access_status": "not_checked", "connection_state": "planned"}, {"agency_code": "ksa", "code": "ksa_certification_info", "name_he": "KSA — ערוצי מידע לצרכן", "url": "https://www.ksakosher.org/", "content_kind": "unspecified", "notes": "עמוד רשמי מקשר לפורטל חיפוש מוצרים וחברות ולהתראות. חברת ייצור אינה זהות של סניף מסעדה. הפורטל לא נבדק לעומק.", "format": "html", "completeness": "unknown", "access_status": "not_checked", "connection_state": "planned"}, {"agency_code": "kosher_check", "code": "kosher_check_consumer_info", "name_he": "Kosher Check — מידע לצרכן", "url": "https://www.koshercheck.org/", "content_kind": "unspecified", "notes": "קישורים לחיפוש מוצרים ול-MyKosher עם כניסה. מוצר או חברה אינם הוכחת כשרות מסעדה. אין API מאושר.", "format": "html", "completeness": "unknown", "access_status": "not_checked", "connection_state": "planned"}, {"agency_code": "earthkosher", "code": "earthkosher_certification_info", "name_he": "EarthKosher — מידע הסמכה", "url": "https://earthkosher.com/", "content_kind": "unspecified", "notes": "מידע על הסמכת יצרנים ולקוחות; לא אותר כאן מדריך בתי עסק מלא או API.", "format": "html", "completeness": "unknown", "access_status": "not_checked", "connection_state": "planned"}, {"agency_code": "eakc", "code": "eakc_certification_info", "name_he": "EAKC — מידע הסמכה", "url": "https://www.eakc.ae/", "content_kind": "unspecified", "notes": "מידע על סימון הגוף והסמכה. לא אותר מדריך עסקים מלא או API ציבורי; נדרשת בדיקה נפרדת.", "format": "html", "completeness": "unknown", "access_status": "not_checked", "connection_state": "planned"}, {"agency_code": "thai_kashrut", "code": "thai_kashrut_consumer_info", "name_he": "TKS — מידע מוצרים", "url": "https://www.thaikashrut.com/about-us/", "content_kind": "unspecified", "notes": "קישורים למידע מוצרים ולרשימות שאינן מחייבות סמל. אין להציג את כל הרשימות כהסמכה ישירה של TKS.", "format": "html", "completeness": "unknown", "access_status": "not_checked", "connection_state": "planned"}, {"agency_code": "kmd_mexico", "code": "kmd_lists", "name_he": "KMD — רשימות לצרכן", "url": "https://www.kosher.com.mx/pages/listas", "content_kind": "unspecified", "notes": "עמוד רשימות מוצרים ובתי עסק שנמצא מקושר באתר. מאפייני קבצים, תחומים, תוקף, מזהים והיתר איסוף לא הושלמו.", "format": "html", "completeness": "unknown", "access_status": "not_checked", "connection_state": "planned"}, {"agency_code": "edah", "code": "edah_customer_services", "name_he": "העדה החרדית — פורטל שירות", "url": "https://cust-info.bdzjr.org/", "content_kind": "certificates", "format": "html", "completeness": "unknown", "access_status": "permission_required", "connection_state": "planned", "notes": "פורטל שירות רשמי לבקשות חומרי גלם ותעודות ללקוחות קיימים. אין בו מדריך בתי עסק ציבורי שנבדק; אין להשתמש בחשבונות לקוחות או טפסים כדי לאסוף נתונים. נדרש אישור וגישה מתאימה לפני כל חיבור."}], "existing_source_audits": [{"code": "beit_shemesh_council", "expected_version": 2, "notes": "2026-10-12: העמוד הרשמי נבדק וקיימת טבלת עסקים. מזהה עסק רשמי קבוע ומועד עדכון לכל רשומה לא אותרו. השדה טלפון משגיח מחוץ לטבלה אינו טלפון עסק. היתר איסוף, תנאי שימוש ותדירות טרם הוכרעו; שלמות לא הוכחה בבדיקת דף."}, {"code": "petah_tikva_council", "expected_version": 2, "notes": "2026-10-12: ספריית בתי העסק הרשמית נבדקה. קיימים דפי סניפים, סיווגי מצב ונתוני משגיח; אלה אינם תוקף תעודה או טלפון העסק. גם פריטי דוח אישי עשויים להופיע ויש להחריגם. נתיב או מזהה WordPress הם מועמדים למזהה, לא הבטחת יציבות. תנאי איסוף ושלמות טרם הוכרעו."}, {"code": "netanya_council", "expected_version": 2, "notes": "2026-10-12: ספריית בתי העסק באתר המועצה הדתית נבדקה כערוץ רשמי. אין מסקנה על יציבות מזהי הסניפים, תדירות, שלמות או תנאי איסוף. אין להציג ספריית עסקים כתעודות מאומתות."}, {"code": "ou_kosher", "expected_version": 2, "notes": "2026-10-12: העמוד הרשמי OU Kosher Supervised Restaurants נבדק. API WordPress ששימש בפיילוט אינו API שאושר כאן לשימוש קבוע. טרם הושלמו בדיקת תנאים, מזהי סניף, שלמות ופירוט תדירות. תוקף ותחום אינם מוסקים מסמל OU."}, {"code": "cor_dining", "expected_version": 1, "notes": "2026-10-12: מדריך טורונטו באתר COR נבדק; קיימים חיפוש, מפה וקטגוריות מסעדות/מאפיות/קצבים/מכולות. החיפוש הדינמי אינו הוכחת רשימה מלאה. תנאי שימוש, מזהים ותדירות דורשים השלמה; אין היתר איסוף מוסק מעצם הצפייה."}, {"code": "mk_dining", "expected_version": 1, "notes": "2026-10-12: מדריך MK מונטריאול נבדק; קיימים שמות, כתובות, סוגי מזון ומחלקות כגון Fish Counter. קיימת טעינת Load More ולכן העמוד הראשון חלקי. אין להרחיב דלפק לסופר כולו. תנאי שימוש, מזהים ותדירות טרם הושלמו."}, {"code": "kosher_australia_products", "expected_version": 1, "notes": "2026-10-12: תנאי השימוש נבדקו מחדש. האיסור המתועד על איסוף אוטומטי נשמר; לא בוצעה כניסה או עקיפה. אין היתר חיבור חדש. הגוף המאומת אינו מעיד שהגישה למאגר מאושרת."}, {"code": "yokneam_government", "expected_version": 2, "notes": "2026-10-12: מטא־נתונים רשמיים אומתו ב-package_show. בעל/מפרסם: המשרד לשירותי דת; שם המשאב מציין רבנות יקנעם עילית. מקור משאב CKAN מכיל 63 רשומות; last_modified=2026-03-24. מלא ביחס לקובץ, לא כיסוי כל העסקים או תעודות בתוקף. _id אינו מזהה סניף קבוע שהוכח. הרשאה לנתוני המאגר נבדקה ברישיון הכללי ובהצהרת isopen=true, license_id=other-open; אין הפעלת איסוף."}]}$research$::jsonb; item jsonb; src jsonb; actual_version integer; subject uuid; count_changed integer;
begin
 -- Validate the complete lease before making any edits.
 for item in select value from jsonb_array_elements(research->'existing_agency_audits') loop
  select version into actual_version from public.weig_kashrut_agencies where code=item->>'code';
  if actual_version is distinct from (item->>'expected_version')::integer then raise exception 'Agency changed: %',item->>'code';end if;
 end loop;
 for item in select value from jsonb_array_elements(research->'existing_source_audits') loop
  select version into actual_version from public.weig_kashrut_registry_sources where code=item->>'code';
  if actual_version is distinct from (item->>'expected_version')::integer then raise exception 'Source changed: %',item->>'code';end if;
 end loop;
 for item in select value from jsonb_array_elements(research->'new_verified_agencies') loop
  if exists(select 1 from public.weig_kashrut_agencies where code=item->>'code') then raise exception 'New agency already registered: %',item->>'code';end if;
 end loop;
 for src in select value from jsonb_array_elements(research->'source_profiles') loop
  if exists(select 1 from public.weig_kashrut_registry_sources where code=src->>'code') then raise exception 'New source already registered: %',src->>'code';end if;
 end loop;
 for item in select value from jsonb_array_elements(research->'existing_agency_audits') loop
  update public.weig_kashrut_agencies set status=item->>'status',official_url=nullif(item->>'official_url',''),
  base_country=coalesce(nullif(item->>'base_country',''),base_country),
  notes=notes||E'\n2026-10-12: בדיקה באמצעות Codex בהוראת מנהל WEIG. '||(item->>'finding')||' מקורות: '||(select string_agg(value,' ; ') from jsonb_array_elements_text(item->'evidence'))||' נותר: '||(item->>'remaining')
  where code=item->>'code' and version=(item->>'expected_version')::integer;
  get diagnostics count_changed=row_count;if count_changed<>1 then raise exception 'Concurrent agency edit';end if;
  if item->>'status'='verified' then
   update public.weig_kashrut_review_tasks r set status='resolved',decision='2026-10-12: זהות הגוף והראיה הרשמית נבדקו באמצעות Codex בהוראת מנהל WEIG. '||(item->>'finding')
   from public.weig_kashrut_agencies a where r.agency_id=a.id and a.code=item->>'code' and r.status in ('open','in_review');
  else
   update public.weig_kashrut_review_tasks r set reason='2026-10-12: '||(item->>'finding')||' להשלמה: '||(item->>'remaining')
   from public.weig_kashrut_agencies a where r.agency_id=a.id and a.code=item->>'code' and r.status in ('open','in_review');
  end if;
 end loop;
 for item in select value from jsonb_array_elements(research->'new_verified_agencies') loop
  insert into public.weig_kashrut_agencies(code,name_he,name_en,kind,official_url,base_country,countries,aliases,status,notes)
  values(item->>'code',item->>'name_he',item->>'name_en',item->>'kind',item->>'official_url',item->>'base_country',
   array(select jsonb_array_elements_text(item->'countries')),array(select jsonb_array_elements_text(item->'aliases')),'verified',item->>'notes');
 end loop;
 for item in select value from jsonb_array_elements(research->'existing_source_audits') loop
  update public.weig_kashrut_registry_sources set notes=notes||E'\n'||(item->>'notes') where code=item->>'code' and version=(item->>'expected_version')::integer;
  get diagnostics count_changed=row_count;if count_changed<>1 then raise exception 'Concurrent source edit';end if;
 end loop;
 -- Explicitly reviewed public-data license only; no key/adapter readiness fabricated.
 update public.weig_kashrut_registry_sources set format='api',coverage='הקובץ הממשלתי שפורסם עבור רבנות יקנעם עילית; 63 רשומות בזמן הבדיקה; לא כיסוי מלא של העיר',
 completeness='full',access_status='allowed',terms_url='https://data.gov.il/he/terms-of-use',
 access_notes='2026-10-12: רישיון מאגרי המידע מאפשר העתקה ושימוש מסחרי עם תנאים וייחוס; מטא־נתוני kosherbusiness מציינים isopen=true, license_id=other-open ולא אותר רישיון ייחודי אחר. גבולות הגישה: API הנתונים הציבורי בלבד; מידע אישי וסמלי המדינה אינם נכללים. בדיקת הרשאה אינה מפעילה חיבור.'
 where code='yokneam_government';
 for src in select value from jsonb_array_elements(research->'source_profiles') loop
  select id into subject from public.weig_kashrut_agencies where code=src->>'agency_code';
  if subject is null then raise exception 'Source agency missing';end if;
  insert into public.weig_kashrut_registry_sources(code,name_he,agency_id,publisher,url,format,status,connection_state,coverage,content_kind,completeness,access_status,access_notes,notes)
  values(src->>'code',src->>'name_he',subject,(select name_en from public.weig_kashrut_agencies where id=subject),src->>'url',src->>'format','verified','planned',src->>'notes',src->>'content_kind','unknown',src->>'access_status',
   case when src->>'access_status'='permission_required' then src->>'notes' else '' end,'2026-10-12: זהות הערוץ אומתה בקישור רשמי. '||(src->>'notes')||' לא נאספו עסקים; אין סורק פעיל. תנאים, מזהים, שלמות ותדירות טרם הושלמו.');
  insert into public.weig_kashrut_review_tasks(subject_type,source_id,title,reason)
  select 'source',id,'השלמת תיק מקור: '||left(name_he,160),'ערוץ רשמי זוהה בלבד. נדרשים תנאי גישה, תחומי נתונים, מזהים, שלמות ותדירות לפני בחינת חיבור; אימות מקור אינו היתר איסוף.'
  from public.weig_kashrut_registry_sources where code=src->>'code';
 end loop;
end $action$;
reset role;
commit;
select jsonb_build_object('agencies',(select count(*) from public.weig_kashrut_agencies),'verified_agencies',(select count(*) from public.weig_kashrut_agencies where status='verified'),'pending_agencies',(select jsonb_agg(code order by code) from public.weig_kashrut_agencies where status<>'verified'),'sources',(select count(*) from public.weig_kashrut_registry_sources),'active_collectors',(select count(*) from public.weig_kashrut_registry_sources where connection_state='active'),'evidence_count',(select count(*) from public.weig_kashrut_evidence)) as result;
